            <ol class="text"><li class="li1"><div class="de1">-- MacroCheat | COMPLETE FUNCTIONS</div></li><li class="li1"><div class="de1">local Library = loadstring(game:HttpGet(&quot;https://raw.githubusercontent.com/bloodball/-back-ups-for-libs/main/wizard&quot;))()</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- Create window</div></li><li class="li1"><div class="de1">local Window = Library:NewWindow(&quot;MacroCheat&quot;, &quot;Bee Swarm Simulator Cheat&quot;)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- Create tabs</div></li><li class="li1"><div class="de1">local MainTab = Window:NewSection(&quot;Main&quot;)</div></li><li class="li1"><div class="de1">local FarmTab = Window:NewSection(&quot;Auto Farm&quot;)</div></li><li class="li1"><div class="de1">local BuyTab = Window:NewSection(&quot;Auto Buy&quot;)</div></li><li class="li1"><div class="de1">local BossTab = Window:NewSection(&quot;Boss Killer&quot;)</div></li><li class="li1"><div class="de1">local PlayerTab = Window:NewSection(&quot;Player&quot;)</div></li><li class="li1"><div class="de1">local TeleportTab = Window:NewSection(&quot;Teleport&quot;)</div></li><li class="li1"><div class="de1">local DupeTab = Window:NewSection(&quot;Dupe System&quot;)</div></li><li class="li1"><div class="de1">local QuestTab = Window:NewSection(&quot;Auto Quest&quot;)</div></li><li class="li1"><div class="de1">local DiscordTab = Window:NewSection(&quot;Discord Stats&quot;)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- Game services</div></li><li class="li1"><div class="de1">local Players = game:GetService(&quot;Players&quot;)</div></li><li class="li1"><div class="de1">local Workspace = game:GetService(&quot;Workspace&quot;)</div></li><li class="li1"><div class="de1">local ReplicatedStorage = game:GetService(&quot;ReplicatedStorage&quot;)</div></li><li class="li1"><div class="de1">local LocalPlayer = Players.LocalPlayer</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- Configuration</div></li><li class="li1"><div class="de1">local Config = {</div></li><li class="li1"><div class="de1">    AutoFarm = false,</div></li><li class="li1"><div class="de1">    GodMode = false,</div></li><li class="li1"><div class="de1">    InfiniteJumps = false,</div></li><li class="li1"><div class="de1">    NoClip = false,</div></li><li class="li1"><div class="de1">    FlyEnabled = false,</div></li><li class="li1"><div class="de1">    Speed = 16,</div></li><li class="li1"><div class="de1">    JumpPower = 50,</div></li><li class="li1"><div class="de1">    FlySpeed = 50,</div></li><li class="li1"><div class="de1">    AutoCollect = true,</div></li><li class="li1"><div class="de1">    AutoConvert = true,</div></li><li class="li1"><div class="de1">    AutoSprinklers = true,</div></li><li class="li1"><div class="de1">    AutoPollen = true,</div></li><li class="li1"><div class="de1">    AutoQuest = false,</div></li><li class="li1"><div class="de1">    AutoQuestBear = &quot;Black Bear&quot;,</div></li><li class="li1"><div class="de1">    AutoQuestDelay = 2,</div></li><li class="li1"><div class="de1">    AutoQuestCompletion = true,</div></li><li class="li1"><div class="de1">    AutoQuestAutoAccept = true,</div></li><li class="li1"><div class="de1">    DupeEnabled = false,</div></li><li class="li1"><div class="de1">    DupeInterval = 5,</div></li><li class="li1"><div class="de1">    MassDupeMode = false,</div></li><li class="li1"><div class="de1">    InjectGameFiles = false,</div></li><li class="li1"><div class="de1">    WebhookURL = &quot;&quot;,</div></li><li class="li1"><div class="de1">    SelectedField = &quot;Sunflower Field&quot;,</div></li><li class="li1"><div class="de1">    SelectedEgg = &quot;Basic Egg&quot;,</div></li><li class="li1"><div class="de1">    SelectedTool = &quot;Basic Wand&quot;,</div></li><li class="li1"><div class="de1">    SelectedBoss = &quot;Stump Snail&quot;,</div></li><li class="li1"><div class="de1">    FarmRadius = 100,</div></li><li class="li1"><div class="de1">    Pattern = &quot;Vortex&quot;,</div></li><li class="li1"><div class="de1">    BossPriority = &quot;All&quot;,</div></li><li class="li1"><div class="de1">    ForceField = false,</div></li><li class="li1"><div class="de1">    ESP = false</div></li><li class="li1"><div class="de1">}</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- All fields</div></li><li class="li1"><div class="de1">local AllFields = {</div></li><li class="li1"><div class="de1">    &quot;Sunflower Field&quot;,</div></li><li class="li1"><div class="de1">    &quot;Mushroom Field&quot;, </div></li><li class="li1"><div class="de1">    &quot;Blue Flower Field&quot;,</div></li><li class="li1"><div class="de1">    &quot;Clover Field&quot;,</div></li><li class="li1"><div class="de1">    &quot;Spider Field&quot;,</div></li><li class="li1"><div class="de1">    &quot;Strawberry Field&quot;,</div></li><li class="li1"><div class="de1">    &quot;Bamboo Field&quot;,</div></li><li class="li1"><div class="de1">    &quot;Pineapple Patch&quot;,</div></li><li class="li1"><div class="de1">    &quot;Stump Field&quot;,</div></li><li class="li1"><div class="de1">    &quot;Cactus Field&quot;,</div></li><li class="li1"><div class="de1">    &quot;Pumpkin Patch&quot;,</div></li><li class="li1"><div class="de1">    &quot;Pine Tree Forest&quot;,</div></li><li class="li1"><div class="de1">    &quot;Rose Field&quot;,</div></li><li class="li1"><div class="de1">    &quot;Mountain Top Field&quot;,</div></li><li class="li1"><div class="de1">    &quot;Coconut Field&quot;,</div></li><li class="li1"><div class="de1">    &quot;Pepper Patch&quot;</div></li><li class="li1"><div class="de1">}</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li cl