ss="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- All bears</div></li><li class="li1"><div class="de1">local AllBears = {</div></li><li class="li1"><div class="de1">    &quot;Black Bear&quot;,</div></li><li class="li1"><div class="de1">    &quot;Brown Bear&quot;, </div></li><li class="li1"><div class="de1">    &quot;Panda Bear&quot;,</div></li><li class="li1"><div class="de1">    &quot;Polar Bear&quot;,</div></li><li class="li1"><div class="de1">    &quot;Science Bear&quot;,</div></li><li class="li1"><div class="de1">    &quot;Dapper Bear&quot;,</div></li><li class="li1"><div class="de1">    &quot;Mother Bear&quot;,</div></li><li class="li1"><div class="de1">    &quot;Gummy Bear&quot;</div></li><li class="li1"><div class="de1">}</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- === AUTO FARM ===</div></li><li class="li1"><div class="de1">FarmTab:CreateToggle(&quot;Auto Farm&quot;, function(value)</div></li><li class="li1"><div class="de1">    Config.AutoFarm = value</div></li><li class="li1"><div class="de1">    if value then</div></li><li class="li1"><div class="de1">        while Config.AutoFarm do</div></li><li class="li1"><div class="de1">            if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(&quot;HumanoidRootPart&quot;) then</div></li><li class="li1"><div class="de1">                local field = Workspace.FlowerZones:FindFirstChild(Config.SelectedField)</div></li><li class="li1"><div class="de1">                if field then</div></li><li class="li1"><div class="de1">                    local offset = Vector3.new(</div></li><li class="li1"><div class="de1">                        math.random(-Config.FarmRadius, Config.FarmRadius),</div></li><li class="li1"><div class="de1">                        5,</div></li><li class="li1"><div class="de1">                        math.random(-Config.FarmRadius, Config.FarmRadius)</div></li><li class="li1"><div class="de1">                    )</div></li><li class="li1"><div class="de1">                    LocalPlayer.Character.HumanoidRootPart.CFrame = field.CFrame + offset</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">                    if Config.AutoCollect then</div></li><li class="li1"><div class="de1">                        pcall(function()</div></li><li class="li1"><div class="de1">                            ReplicatedStorage.Events.PollenFromTool:FireServer()</div></li><li class="li1"><div class="de1">                        end)</div></li><li class="li1"><div class="de1">                    end</div></li><li class="li1"><div class="de1">                end</div></li><li class="li1"><div class="de1">            end</div></li><li class="li1"><div class="de1">            wait(0.1)</div></li><li class="li1"><div class="de1">        end</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">FarmTab:CreateDropdown(&quot;Field Selection&quot;, AllFields, function(option)</div></li><li class="li1"><div class="de1">    Config.SelectedField = option</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">FarmTab:CreateSlider(&quot;Farm Radius&quot;, 10, 500, 100, function(value)</div></li><li class="li1"><div class="de1">    Config.FarmRadius = value</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">FarmTab:CreateDropdown(&quot;Farm Pattern&quot;, {&quot;Vortex&quot;, &quot;Circular&quot;, &quot;Square&quot;, &quot;Random&quot;}, function(option)</div></li><li class="li1"><div class="de1">    Config.Pattern = option</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- === AUTO BUY ===</div></li><li class="li1"><div class="de1">BuyTab:CreateToggle(&quot;Auto Buy&quot;, function(value)</div></li><li class="li1"><div class="de1">    if value then</div></li><li class="li1"><div class="de1">        while Config.AutoBuyEnabled do</div></li><li class="li1"><div class="de1">            pcall(function()</div></li><li class="li1"><div class="de1">                ReplicatedStorage.Events.BuyEgg:InvokeServer(Config.SelectedEgg)</div></li><li class="li1"><div class="de1">                ReplicatedStorage.Events.BuyTool:InvokeServer(Config.SelectedTool)</div></li><li class="li1"><div class="de1">            end)</div></li><li class="li1"><div class="de1">            wait(5)</div></li><li class="li1"><div class="de1">        end</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">    Config.AutoBuyEnabled = value</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">BuyTab:CreateDropdown(&quot;Egg Selection&quot;, AllEggs, function(option)</div></li><li class="li1"><div class="de1">    Config.SelectedEgg = option</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">BuyTab:CreateDropdown(&quot;Tool Selection&quot;, AllTools, function(option)</div></li><li class="li1"><div class="de1">    Config.SelectedTool = option</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">BuyTab:CreateSlider(&quot;Buy Amount&quot;, 1, 100, 1, function(value)</div></li><li class="li1"><div class="de1">    Config.BuyAmount = value</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- === BOSS KILLER ===</div></li><li class="li1"><div class="de1">BossTab:CreateToggle(&quot;Boss Killer&quot;, function(value)</div></li><li class="li1"><div class="de1">    Config.BossKilling = value</div></li><li class="li1"><div class="de1">    if value then</div></li><li class="li1"><div class="de1">        while Config.BossKilling do</div></li><li class="li1"><div class="de1">            local boss = Workspace.Monsters:FindFirstChild(Config.SelectedBoss)</div></li><li class="li1"><div class="de1">            if boss and boss:FindFirstChild(&quot;HumanoidRootPart&quot;) then</div></li><li class="li1"><div class="de1">                if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(&quot;HumanoidRootPart&quot;) then</div></li><li class="li1"><div class="de1">                    LocalPlayer.Character.HumanoidRootPart.CFrame = boss.HumanoidRootPart.CFrame + Vector3.new(0, 0, -10)</div></li><li class="li1"><div class="de1">                    pcall(function()</div></li><li class="li1"><div class="de1">                        ReplicatedStorage.Events.DamageBoss:FireServer(boss)</div></li><li class="li1"><div class="de1">                    end)</div></li><li class="li1"><div class="de1">                end</div></li><li class="li1"><div class="de1">            end</div></li><li class="li1"><div class="de1">            wait(0.5)</div></li><li class="li1"><div class="de1">        end</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">BossTab:CreateDropdown(&quot;Boss Selection&quot;, AllBosses, function(option)</div></li><li class="li1"><div class="de1">    Config.SelectedBoss = option</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- === PLAYER ===</div></li><li class="li1"><div class="de1">PlayerTab:CreateToggle(&quot;God Mode&quot;, function(value)</div></li><li class="li1"><div class="de1">    Config.GodMode = value</div></li><li class="li1"><div class="de1">    if value then</div></li><li class="li1"><div class="de1">        while Config.GodMode do</div></li><li class="li1"><div class="de1">            if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(&quot;Humanoid&quot;) then</div></li><li class="li1"><div class="de1">                LocalPlayer.Character.Humanoid.Health = LocalPlayer.Character.Humanoid.MaxHealth</div></li><li class="li1"><div class="de1">            end</div></li><li class="li1"><div class="de1">            wait(0.1)</div></li><li class="li1"><div class="de1">        end</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">PlayerTab:CreateSlider(&quot;Walk Speed&quot;, 16, 500, 16, function(value)</div></li><li class="li1"><div class="de1">    Config.Speed = value</div></li><li class="li1"><div class="de1">    if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(&quot;Humanoid&quot;) then</div></li><li class="li1"><div class="de1">        LocalPlayer.Character.Humanoid.WalkSpeed = value</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">PlayerTab:CreateSlider(&quot;Jump Power&quot;, 50, 1000, 50, function(value)</div></li><li class="li1"><div class="de1">    Config.JumpPower = value</div></li><li class="li1"><div class="de1">    if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(&quot;Humanoid&quot;) then</div></li><li class="li1"><div class="de1">        LocalPlayer.Character.Humanoid.JumpPower = value</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">PlayerTab:CreateToggle(&quot;Fly Mode&quot;, function(value)</div></li><li class="li1"><div class="de1">    Config.FlyEnabled = value</div></li><li class="li1"><div class="de1">    if value then</div></li><li class="li1"><div class="de1">        local BodyVelocity = Instance.new(&quot;BodyVelocity&quot;)</div></li><li class="li1"><div class="de1">        BodyVelocity.Velocity = Vector3.new(0, 0, 0)</div></li><li class="li1"><div class="de1">        BodyVelocity.MaxForce = Vector3.new(10000, 10000, 10000)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">        while Config.FlyEnabled do</div></li><li class="li1"><div class="de1">            if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(&quot;HumanoidRootPart&quot;) then</div></li><li class="li1"><div class="de1">                local root = LocalPlayer.Character.HumanoidRootPart</div></li><li class="li1"><div class="de1">                BodyVelocity.Parent = root</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">                local UserInputService = game:GetService(&quot;UserInputService&quot;)</div></li><li class="li1"><div class="de1">                local velocity = Vector3.new(0, 0, 0)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">                if UserInputService:IsKeyDown(Enum.KeyCode.W) then</div></li><li class="li1"><div class="de1">                    velocity = velocity + (root.CFrame.LookVector * Config.FlySpeed)</div></li><li class="li1"><div class="de1">                end</div></li><li class="li1"><div class="de1">                if UserInputService:IsKeyDown(Enum.KeyCode.S) then</div></li><li class="li1"><div class="de1">                    velocity = velocity + (root.CFrame.LookVector * -Config.FlySpeed)</div></li><li class="li1"><div class="de1">                end</div></li><li class="li1"><div class="de1">                if UserInputService:IsKeyDown(Enum.KeyCode.A) then</div></li><li class="li1"><div class="de1">                    velocity = velocity + (root.CFrame.RightVector * -Config.FlySpeed)</div></li><li class="li1"><div class="de1">                end</div></li><li class="li1"><div class="de1">                if UserInputService:IsKeyDown(Enum.KeyCode.D) then</div></li><li class="li1"><div class="de1">                    velocity = velocity + (root.CFrame.RightVector * Config.FlySpeed)</div></li><li class="li1"><div class="de1">                end</div></li><li class="li1"><div class="de1">                if UserInputService:IsKeyDown(Enum.KeyCode.Space) then</div></li><li class="li1"><div class="de1">                    velocity = velocity + Vector3.new(0, Config.FlySpeed, 0)</div></li><li class="li1"><div class="de1">                end</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">                BodyVelocity.Velocity = velocity</div></li><li class="li1"><div class="de1">            end</div></li><li class="li1"><div class="de1">            wait()</div></li><li class="li1"><div class="de1">        end</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">        BodyVelocity:Destroy()</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">PlayerTab:CreateSlider(&quot;Fly Speed&quot;, 20, 300, 50, function(value)</div></li><li class="li1"><div class="de1">    Config.FlySpeed = value</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">PlayerTab:CreateToggle(&quot;No Clip&quot;, function(value)</div></li><li class="li1"><div class="de1">    Config.NoClip = value</div></li><li class="li1"><div class="de1">    if value then</div></li><li class="li1"><div class="de1">        while Config.NoClip do</div></li><li class="li1"><div class="de1">            if LocalPlayer.Character then</div></li><li class="li1"><div class="de1">                for _, part in pairs(LocalPlayer.Character:GetDescendants()) do</div></li><li class="li1"><div class="de1">                    if part:IsA(&quot;BasePart&quot;) then</div></li><li class="li1"><div class="de1">                        part.CanCollide = false</div></li><li class="li1"><div class="de1">                    end</div></li><li class="li1"><div class="de1">                end</div></li><li class="li1"><div class="de1">            end</div></li><li class="li1"><div class="de1">            wait(0.1)</div></li><li class="li1"><div class="de1">        end</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">PlayerTab:CreateToggle(&quot;Infinite Jump&quot;, function(value)</div></li><li class="li1"><div class="de1">    Config.InfiniteJumps = value</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- INFINITE JUMP</div></li><li class="li1"><div class="de1">game:GetService(&quot;UserInputService&quot;).JumpRequest:Connect(function()</div></li><li class="li1"><div class="de1">    if Config.InfiniteJumps and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(&quot;Humanoid&quot;) then</div></li><li class="li1"><div class="de1">        LocalPlayer.Character.Humanoid:ChangeState(&quot;Jumping&quot;)</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- === TELEPORT ===</div></li><li class="li1"><