ld(&quot;HumanoidRootPart&quot;) then</div></li><li class="li1"><div class="de1">        LocalPlayer.Character.HumanoidRootPart.CFrame = bear.HumanoidRootPart.CFrame + Vector3.new(0, 0, -5)</div></li><li class="li1"><div class="de1">        Library:Notification(&quot;Teleported to Black Bear&quot;)</div></li><li class="li1"><div class="de1">    end</div></li><li class="li1"><div class="de1">end)</div></li><li class="li1"><div class="de1">&nbsp;</div></li><li class="li1"><div class="de1">-- === DUPE SYSTEM ===</div></li><li class="li1"><div class="de1">DupeTab:CreateToggle(&quot;Auto Dupe&quot;, function(value)</div></li><li class="li1"><div class="de1">    Config.DupeEnabled = value</div></li><li class="li1"><div class="de1">    if value then</div></li><li class="li1"><div class="de1">        while Config.DupeEnabled do</div></li><li class="li1"><div class="de1">            for i = 1, 10 do</div></li><li class="li1"><div class="de1">                pcall(function()</div></li><li class="li1"><div class="de1">                    if ReplicatedStorage:FindFirstChild(&quot;Events&quot;) then</div></li><li class="li1"><div class="de1">                        local event = ReplicatedStorage.Events:FindFirstChild(&quot;AddCurrency&quot;)</div></li><li class="li1"><div class="de1">                        if event then</div></li><li class="li1"><div class="de1">                            event:FireServer(&quot;Honey&quot;, 999999)</div></li><li class="li1"><div class="de1">                            event:FireServer(&quot;Pollen&quot;, 999999)</div></li><li class="li1"><div class="de1">                        end</div></li><li class="li1"><div class="de1">                    end</div></li><li class="li1"><div class="de1">                end)</div></li><li class="li1"><div class="de1">            end</div></li><li class="li1"><div class="de1">            wait(Config.DupeInterval)</div></li><li class="li1"><div class="de1">        end</div></li><li clas